new = '''def build_full_code(problem, solution):
    if problem["source"] == "humaneval":
        first_line = solution.lstrip().split("\\n")[0] if solution.strip() else ""
        if first_line.startswith("def ") and problem["entry_point"] in first_line:
            return solution
        # Auto-indent: find expected indent from prompt's last non-empty line
        prompt_lines = problem["prompt"].rstrip().split("\\n")
        expected_indent = 4
        for line in reversed(prompt_lines):
            stripped = line.lstrip()
            if stripped:
                expected_indent = len(line) - len(stripped)
                break
        # Check actual indent of solution's first non-empty line
        actual_indent = 0
        for line in solution.split("\\n"):
            if line.strip():
                actual_indent = len(line) - len(line.lstrip())
                break
        if actual_indent < expected_indent:
            pad = " " * (expected_indent - actual_indent)
            solution = "\\n".join(
                pad + line if line.strip() else line
                for line in solution.split("\\n")
            )
        return problem["prompt"] + solution
    return solution'''

